/* Banco de preguntas de Economía de la Salud. Selección múltiple y verdadero/falso, basado en los temas del ramo. Sin IA. */
const BANCO_ECONOMIA = [
  // Personas, incentivos y decisiones
  { lesson: 'econ-incentivos', type: 'mc', prompt: 'Ejercicio simulado: una hora de pabellón puede destinarse a la cirugía A (beneficio estimado de 30 unidades), a la B (25 unidades) o a la C (20 unidades). Si se elige A, ¿cuál es el costo de oportunidad?', options: ['25 unidades: el beneficio de B, la mejor alternativa sacrificada.', '45 unidades: la suma de los beneficios de B y C.', '20 unidades: el beneficio de la alternativa menos valiosa.', 'Cero, porque usar el pabellón no exige ningún pago adicional al hospital.'], explanation: 'El costo de oportunidad es el valor de la mejor alternativa viable que se deja de realizar, no la suma de todas. Con una sola hora disponible se sacrifica B (25). No depende de que exista un pago adicional.' },
  { lesson: 'econ-incentivos', type: 'mc', prompt: 'Un hospital ofrece un bono a quienes completen un curso de capacitación. ¿Cómo se clasifica ese bono según la clase?', options: ['Como un incentivo externo que puede influir en la conducta.', 'Como una motivación intrínseca del personal capacitado.', 'Como una motivación trascendente, porque ayuda al paciente.', 'Como una necesidad que se transforma en demanda efectiva.'], explanation: 'La motivación es interna a la persona; el bono es una condición externa, es decir, un incentivo. Puede activar motivación extrínseca, pero su efecto depende de la persona y del contexto.' },
  { lesson: 'econ-incentivos', type: 'mc', prompt: 'Una kinesióloga disfruta resolver bien cada caso clínico, aunque nadie lo reconozca y no reciba pago extra. ¿Qué tipo de motivación describe la situación?', options: ['Motivación intrínseca.', 'Motivación extrínseca.', 'Motivación trascendente.', 'Incentivo monetario.'], explanation: 'La motivación intrínseca proviene de la satisfacción de realizar bien la tarea. La extrínseca depende de recompensas como sueldo o reconocimiento, y la trascendente del efecto del trabajo en otras personas.' },
  { lesson: 'econ-incentivos', type: 'mc', prompt: 'Un consultorio paga un bono según el número de consultas realizadas por cada profesional. ¿Qué efecto no deseado advierte el material?', options: ['Que aumente el volumen, pero se acorte la duración de la atención.', 'Que disminuya necesariamente el número total de consultas.', 'Que desaparezca la motivación intrínseca de todo el equipo.', 'Que el bono pase a ser una forma de motivación trascendente.'], explanation: 'Un bono por volumen puede elevar la cantidad de consultas, pero también acortar la atención. Su diseño se evalúa observando acceso, calidad, esfuerzo y posibles conductas no deseadas, no solo el volumen.' },
  { lesson: 'econ-incentivos', type: 'mc', prompt: '¿Por qué una asignación de prestaciones basada exclusivamente en precios puede dejar necesidades de salud sin atender?', options: ['Porque la demanda efectiva exige disposición y capacidad de pago, no solo necesidad.', 'Porque los precios no influyen en la cantidad de prestaciones que se demanda.', 'Porque toda necesidad sanitaria se convierte automáticamente en demanda efectiva de mercado.', 'Porque el costo de oportunidad de una prestación de salud siempre es cero.'], explanation: 'Necesitar una prestación no garantiza poder pagarla. La demanda efectiva incorpora disposición y capacidad de pago; quien necesita atención pero no puede pagarla queda fuera de una asignación solo por precios.' },
  { lesson: 'econ-incentivos', type: 'mc', prompt: 'En el análisis económico, ¿qué implica suponer que las personas actúan según su interés propio?', options: ['Que es un supuesto de análisis, no una prueba de egoísmo general.', 'Que el dinero es la única motivación relevante de cualquier persona.', 'Que las personas no responden a las restricciones ni a los incentivos.', 'Que la conducta de las personas no cambia frente a nuevas reglas.'], explanation: 'El interés propio se usa como herramienta para analizar cómo responden las personas a restricciones e incentivos. No afirma que todos sean egoístas ni que el dinero sea la única motivación.' },
  { lesson: 'econ-incentivos', type: 'tf', prompt: 'La escasez obliga a elegir, porque los recursos tienen usos alternativos que compiten entre sí.', answer: true, explanation: 'Correcto. Como los recursos son escasos y tienen usos alternativos, usarlos en una opción implica renunciar a otra; de ahí surge el costo de oportunidad.' },
  { lesson: 'econ-incentivos', type: 'tf', prompt: 'Una misma persona puede combinar motivación intrínseca, extrínseca y trascendente en su trabajo.', answer: true, explanation: 'Correcto. Una enfermera puede disfrutar enseñar (intrínseca), recibir un bono de capacitación (extrínseca) y valorar que la familia cuide mejor al paciente (trascendente).' },
  { lesson: 'econ-incentivos', type: 'tf', prompt: 'El costo de oportunidad de usar una hora de pabellón se limita al dinero pagado por esa hora.', answer: false, explanation: 'Falso. El costo de oportunidad incluye el beneficio de la mejor cirugía alternativa viable que no se realiza; no se reduce al dinero pagado por el recurso.' },
  { lesson: 'econ-incentivos', type: 'tf', prompt: 'La motivación trascendente corresponde al sueldo, el reconocimiento y las condiciones laborales.', answer: false, explanation: 'Falso. Sueldo, reconocimiento y condiciones laborales corresponden a motivación extrínseca. La trascendente se refiere al efecto del trabajo en otras personas, como mejorar la experiencia de un paciente.' },

  // Flujo circular, eficiencia y equidad
  { lesson: 'econ-flujo', type: 'mc', prompt: 'En el flujo circular, ¿qué recorre el circuito real desde los hogares hacia las empresas?', options: ['Trabajo y otros factores de producción.', 'Remuneraciones y otras rentas.', 'Bienes y servicios terminados.', 'Gasto en consumo realizado por los hogares.'], explanation: 'El circuito real lleva trabajo y otros factores desde los hogares a las empresas, y bienes y servicios en sentido inverso. Remuneraciones y gasto pertenecen al circuito monetario.' },
  { lesson: 'econ-flujo', type: 'mc', prompt: 'Un laboratorio clínico paga remuneraciones a una tecnóloga médica y recibe pagos de pacientes y aseguradores por los exámenes. ¿Qué afirmación es correcta?', options: ['Lo que gastan pacientes y aseguradores es ingreso del laboratorio, pero no es utilidad.', 'Todo el ingreso del laboratorio es utilidad, porque proviene del gasto de otros agentes.', 'Las remuneraciones pagadas a la tecnóloga forman parte del circuito real, no del monetario.', 'El laboratorio aporta factores de producción a los hogares a cambio de su gasto.'], explanation: 'El gasto de una parte es ingreso de otra, pero ingreso no es utilidad: el laboratorio aún debe cubrir remuneraciones, insumos y otros costos. Las remuneraciones circulan por el circuito monetario.' },
  { lesson: 'econ-flujo', type: 'mc', prompt: '¿Qué diferencia la eficacia de la eficiencia?', options: ['Eficacia es cumplir el objetivo; eficiencia relaciona resultados con recursos.', 'Eficacia relaciona resultados con recursos; eficiencia es cumplir el objetivo.', 'Ambas significan atender más pacientes por hora de trabajo disponible.', 'Eficacia mide la distribución; eficiencia mide la necesidad de la población.'], explanation: 'Eficacia significa lograr el objetivo propuesto; eficiencia vincula los resultados con los recursos utilizados. Un programa puede ser eficaz y, aun así, usar más recursos de los necesarios.' },
  { lesson: 'econ-flujo', type: 'mc', prompt: 'El centro de salud A atiende más pacientes por hora que el centro B. ¿Qué se necesita para afirmar que A es más eficiente?', options: ['Ajustar por calidad, complejidad de los pacientes y tipo de productos.', 'Nada adicional: atender más pacientes por hora prueba mayor eficiencia.', 'Comparar únicamente el gasto total anual de ambos centros.', 'Verificar que A tenga más profesionales contratados que B.'], explanation: 'Atender más pacientes por sí solo no demuestra mayor eficiencia. Hay que comparar recursos y resultados ajustando calidad, complejidad y productos; reducir tiempo a costa de calidad no mejora el desempeño.' },
  { lesson: 'econ-flujo', type: 'mc', prompt: 'Un programa entrega el mismo monto por habitante a todas las comunas, aunque algunas enfrentan mayor riesgo y barreras de acceso. ¿Qué criterio aplica?', options: ['Igualdad, que puede no ser equitativa si las necesidades difieren.', 'Equidad, porque todas las comunas reciben el mismo monto.', 'Eficiencia productiva, porque usa el mínimo de recursos.', 'Eficacia, porque asegura cumplir el objetivo sanitario.'], explanation: 'Dar lo mismo a todos es igualdad. La equidad considera necesidades y barreras, y puede justificar más apoyo a quienes enfrentan mayor riesgo; por eso igualdad no garantiza equidad.' },
  { lesson: 'econ-flujo', type: 'mc', prompt: 'Un país gasta más en salud por persona que otro. ¿Qué permite afirmar ese dato por sí solo?', options: ['Que usa más recursos, sin probar mejor calidad ni causalidad.', 'Que su población tiene necesariamente mejores resultados de salud.', 'Que su sistema de salud es más eficiente que el del otro país.', 'Que el gasto sanitario es la única causa de sus resultados.'], explanation: 'El gasto describe recursos, no prueba calidad ni causalidad. Los resultados dependen también de educación, entorno, condiciones sociales, conductas y atención sanitaria.' },
  { lesson: 'econ-flujo', type: 'tf', prompt: 'Además de recaudar y redistribuir, el Estado puede regular y también prestar servicios dentro del flujo circular.', answer: true, explanation: 'Correcto. Según el documento, el Estado recauda, redistribuye, regula y también presta servicios; los sistemas reales combinan instituciones y criterios.' },
  { lesson: 'econ-flujo', type: 'tf', prompt: 'La eficiencia productiva consiste en producir un resultado con el menor uso de recursos, para una calidad definida.', answer: true, explanation: 'Correcto. La referencia a una calidad definida evita confundir eficiencia con una simple reducción de recursos o con un aumento de volumen.' },
  { lesson: 'econ-flujo', type: 'tf', prompt: 'Eficiencia y equidad son el mismo criterio, por lo que lograr una garantiza automáticamente la otra.', answer: false, explanation: 'Falso. La eficiencia relaciona resultados y recursos; la equidad considera necesidades y distribución. Son criterios distintos que deben discutirse juntos.' },
  { lesson: 'econ-flujo', type: 'tf', prompt: 'Los resultados de salud de una población dependen exclusivamente de la atención sanitaria que recibe.', answer: false, explanation: 'Falso. Educación, entorno, condiciones sociales, conductas y atención sanitaria contribuyen a los resultados de salud; la atención es solo uno de esos factores.' },

  // Particularidades de los mercados de salud
  { lesson: 'econ-fallas', type: 'mc', prompt: '¿Qué dos características definen un bien público puro?', options: ['No rivalidad en el consumo y no exclusión.', 'Financiamiento con impuestos y acceso gratuito.', 'Rivalidad en el consumo y posibilidad de exclusión.', 'Provisión estatal y ausencia de fines de lucro.'], explanation: 'Un bien público puro combina no rivalidad y no exclusión. El financiamiento con impuestos o la provisión estatal no cambian por sí solos la naturaleza económica de un bien.' },
  { lesson: 'econ-fallas', type: 'mc', prompt: 'Un box de atención de un consultorio municipal se financia con impuestos, atiende a un paciente a la vez y su uso se asigna por agenda. ¿Cómo se clasifica económicamente?', options: ['Como bien privado, porque es rival y excluible.', 'Como bien público puro, porque lo financia el Estado.', 'Como externalidad positiva, porque sirve a la comuna.', 'Como bien no rival, porque no se cobra al paciente.'], explanation: 'El box es rival (no lo usan dos pacientes a la vez) y se puede restringir su acceso. Por eso es un bien privado en la clasificación económica, aunque su financiamiento sea público.' },
  { lesson: 'econ-fallas', type: 'mc', prompt: '¿Qué describe el problema del polizón en relación con los bienes públicos?', options: ['Beneficiarse de un bien sin contribuir a su financiamiento.', 'Usar más servicios después de contratar un seguro de salud.', 'Ocultar el propio riesgo al contratar una póliza de salud.', 'Atender más pacientes de los que permite la capacidad.'], explanation: 'El polizón obtiene el beneficio de un bien público sin contribuir a él, lo que es posible porque no se puede excluir. Usar más servicios tras asegurarse corresponde a riesgo moral, no al polizón.' },
  { lesson: 'econ-fallas', type: 'mc', prompt: 'Una vacuna reduce la transmisión de una enfermedad y protege también a personas que no se vacunaron. ¿Qué concepto ilustra ese efecto?', options: ['Externalidad positiva.', 'Beneficio privado.', 'Información asimétrica.', 'Selección adversa.'], explanation: 'Una externalidad afecta a terceros fuera de la transacción. La protección de quienes no se vacunaron es distinta del beneficio privado que obtiene la persona vacunada.' },
  { lesson: 'econ-fallas', type: 'mc', prompt: 'Un médico conoce mejor que su paciente las opciones de tratamiento. Según el material, ¿qué implica esa información asimétrica?', options: ['Que poseen información distinta, sin que alguno deba estar mintiendo.', 'Que existe necesariamente un fraude por parte del profesional tratante.', 'Que el paciente no puede demandar ninguna prestación de salud.', 'Que la relación funciona igual que un mercado competitivo simple.'], explanation: 'La asimetría significa que profesional y paciente tienen información distinta; no requiere que alguien mienta ni equivale automáticamente a fraude. Sí es una particularidad que distingue a los mercados de salud.' },
  { lesson: 'econ-fallas', type: 'mc', prompt: 'Según las precisiones del material, ¿qué significa que un hospital sea una entidad sin fines de lucro?', options: ['Que tiene restricciones para distribuir sus excedentes.', 'Que cobra siempre precios más bajos que otros prestadores.', 'Que goza de exención tributaria en cualquier jurisdicción.', 'Que no puede registrar ingresos superiores a sus costos.'], explanation: 'Sin fines de lucro se refiere a restricciones a la distribución de excedentes. No garantiza por sí solo precios bajos ni una exención tributaria universal, que depende de cada jurisdicción.' },
  { lesson: 'econ-fallas', type: 'tf', prompt: 'La contaminación de una fábrica que impone costos de salud a vecinos ajenos a su producción es una externalidad negativa.', answer: true, explanation: 'Correcto. Los vecinos no participan en la transacción, pero soportan costos. Por eso el costo social de esa producción puede superar su costo privado.' },
  { lesson: 'econ-fallas', type: 'tf', prompt: 'Los seguros de salud protegen frente a gastos inciertos, pero también pueden alterar los incentivos de quienes participan.', answer: true, explanation: 'Correcto. Los seguros reducen el riesgo financiero de enfermar, pero cambian incentivos; por eso la importancia de los seguros es una de las particularidades del sector.' },
  { lesson: 'econ-fallas', type: 'tf', prompt: 'Si una prestación pasa a financiarse con impuestos, se convierte automáticamente en un bien público puro.', answer: false, explanation: 'Falso. Financiamiento y naturaleza económica son dimensiones distintas. Un bien público puro requiere no rivalidad y no exclusión, independiente de quién lo pague.' },
  { lesson: 'econ-fallas', type: 'tf', prompt: 'En salud, la enfermedad y la respuesta a los tratamientos son predecibles, por lo que la incertidumbre no es una particularidad del sector.', answer: false, explanation: 'Falso. La enfermedad y la respuesta a tratamientos son inciertas; incertidumbre y riesgo encabezan las ocho particularidades que el apunte organiza siguiendo a Phelps.' },

  // Principal, agente y mecanismos de pago
  { lesson: 'econ-agencia', type: 'mc', prompt: '¿Cuándo surge un problema de agencia entre un principal y un agente?', options: ['Cuando sus objetivos difieren y cuesta observar decisiones, esfuerzo o calidad.', 'Cuando el agente recibe cualquier tipo de remuneración fija o variable por su trabajo.', 'Cuando principal y agente comparten exactamente los mismos objetivos.', 'Solo cuando el agente actúa en forma deshonesta o ilegal.'], explanation: 'El principal delega y el agente actúa con información que el principal no observa por completo. El problema aparece si los objetivos difieren y es difícil observar decisiones, esfuerzo o calidad; no supone deshonestidad.' },
  { lesson: 'econ-agencia', type: 'mc', prompt: 'Un centro de atención primaria recibe un monto fijo por cada persona inscrita, independiente de cuántas atenciones entregue. ¿Qué riesgo es característico de este pago?', options: ['Subprestación y selección de personas de menor costo.', 'Sobreprestación para aumentar el número de atenciones.', 'Descuidar solo los aspectos que no mide una meta.', 'Inestabilidad del ingreso mensual de sus profesionales.'], explanation: 'La capitación incentiva controlar costos, con riesgo de subprestación y de selección. La sobreprestación es el riesgo típico del pago por servicio, donde el ingreso crece con cada prestación.' },
  { lesson: 'econ-agencia', type: 'mc', prompt: 'Un especialista recibe un pago por cada procedimiento que realiza. ¿Qué incentivo potencial genera este pago por servicio?', options: ['Sobreprestación, porque su ingreso aumenta con las prestaciones.', 'Subprestación, porque cada atención adicional reduce su ingreso.', 'Selección de personas de bajo riesgo entre los inscritos.', 'Indiferencia frente al volumen, porque su ingreso es fijo.'], explanation: 'En el pago por servicio el ingreso crece con el número de prestaciones, lo que puede inducir sobreprestación. Es un riesgo posible, no una conducta inevitable; la subprestación se asocia más a la capitación.' },
  { lesson: 'econ-agencia', type: 'mc', prompt: 'Tras adoptar pago por caso (GRD), un hospital redujo su estancia media. ¿Qué debe evaluarse antes de concluir que la atención mejoró?', options: ['Reingresos, resultados clínicos, complejidad de los pacientes y acceso.', 'Solo el número de egresos, porque más egresos prueban una mejora.', 'Únicamente los días cama ahorrados durante el último trimestre.', 'Ningún otro dato, porque una menor estancia siempre indica mayor eficiencia.'], explanation: 'Una estancia menor con más reingresos evitables puede ser una falsa economía. Hay que revisar reingresos, resultados, complejidad y acceso antes de atribuir una mejora al cambio de pago.' },
  { lesson: 'econ-agencia', type: 'mc', prompt: '¿Qué riesgo se asocia típicamente al pago por desempeño?', options: ['Descuidar los aspectos de la atención que no se miden.', 'Sobreprestación por cada prestación facturada.', 'Subprestación por un monto fijo por persona inscrita.', 'Pérdida de toda orientación hacia metas definidas.'], explanation: 'El pago por desempeño orienta la atención hacia metas, pero puede llevar a descuidar lo que no se mide. Por eso se combina con medición amplia de calidad y seguimiento de resultados.' },
  { lesson: 'econ-agencia', type: 'mc', prompt: '¿Qué ventaja y qué riesgo se asocian al pago por salario?', options: ['Facilita estabilidad, pero puede debilitar el incentivo al volumen.', 'Fomenta el volumen, pero genera ingresos inestables y variables.', 'Controla costos por inscrito, pero induce selección de riesgos.', 'Garantiza la calidad, pero eleva el costo administrativo total.'], explanation: 'El salario da estabilidad al profesional, pero como no depende del número de prestaciones puede debilitar el incentivo al volumen. Ningún mecanismo de pago garantiza calidad por sí solo.' },
  { lesson: 'econ-agencia', type: 'tf', prompt: 'Mezclar mecanismos de pago, ajustar por complejidad y medir calidad ayuda a equilibrar los riesgos de cada forma de pago.', answer: true, explanation: 'Correcto. Cada pago genera incentivos posibles, como sobreprestación o subprestación; combinarlos con ajuste de riesgo y medición de calidad ayuda a contrarrestarlos.' },
  { lesson: 'econ-agencia', type: 'tf', prompt: 'En la función de utilidad U = f(Y, L, P, Q) del médico, la letra Q representa calidad o bienestar del paciente, no cantidad de mercado.', answer: true, explanation: 'Correcto. La función indica que el médico valora ingreso (Y), ocio (L), prestigio (P) y bienestar del paciente (Q). Es una representación de preferencias, no una fórmula numérica universal.' },
  { lesson: 'econ-agencia', type: 'tf', prompt: 'Un mecanismo de pago bien diseñado, como el pago por caso, garantiza por sí solo la calidad de la atención.', answer: false, explanation: 'Falso. Ningún pago garantiza calidad: se necesitan medición, ajuste de riesgo y seguimiento de resultados.' },
  { lesson: 'econ-agencia', type: 'tf', prompt: 'En todo sistema de pago por GRD, un reingreso queda automáticamente sin pago.', answer: false, explanation: 'Falso. Que un reingreso se pague o no depende de las reglas concretas de cada sistema; no es una característica automática del pago por GRD.' },

  // Grossman: salud como capital
  { lesson: 'econ-grossman', type: 'mc', prompt: 'Ejercicio simulado: en el modelo de Grossman, H(t) = 120, δ = 5% e I(t) = 10. ¿Cuánto vale H(t+1)?', options: ['124 unidades', '130 unidades', '114 unidades', '16 unidades'], explanation: 'H(t+1) = 120 × (1 − 0,05) + 10 = 114 + 10 = 124. El valor 130 olvida la depreciación de 6 unidades y 114 omite la inversión.' },
  { lesson: 'econ-grossman', type: 'mc', prompt: 'Ejercicio simulado: con H(t) = 150 y δ = 8%, ¿qué inversión I(t) mantiene constante el stock de salud en ese período?', options: ['12 unidades', '8 unidades', '138 unidades', '162 unidades'], explanation: 'Para mantener el stock, la inversión debe compensar la depreciación: I = δ × H = 0,08 × 150 = 12. El valor 138 es el stock que quedaría sin inversión, no la inversión requerida.' },
  { lesson: 'econ-grossman', type: 'mc', prompt: 'Ejercicio simulado: H(t) = 90, δ = 10% y no hay inversión durante dos períodos consecutivos. ¿Cuánto vale el stock al final del segundo período?', options: ['72,9 unidades', '72 unidades', '81 unidades', '70 unidades'], explanation: 'Cada período se pierde 10% del stock vigente: 90 × 0,90 = 81 y luego 81 × 0,90 = 72,9. Restar dos veces el 10% del valor inicial (72) ignora que la depreciación se aplica sobre el stock que queda.' },
  { lesson: 'econ-grossman', type: 'mc', prompt: 'Según el modelo de capital de salud de Grossman, ¿qué papel cumple la atención médica?', options: ['Es un insumo para producir salud, que es lo que se valora.', 'Es el bien final que las personas valoran por sí mismo.', 'Es la tasa a la que se deprecia el stock de salud.', 'Es un sustituto perfecto del tiempo y de la educación de la persona.'], explanation: 'Las personas demandan salud por sus beneficios de consumo e inversión; la atención médica es uno de sus insumos, junto con tiempo y educación: H = f(M, T, E).' },
  { lesson: 'econ-grossman', type: 'mc', prompt: '¿Qué representa δ en la ecuación H(t+1) = H(t) × (1 − δ) + I(t)?', options: ['La fracción del stock de salud que se pierde en un período.', 'La inversión neta que se agrega al stock en cada período.', 'El gasto en pesos destinado a atención médica en el período.', 'El valor máximo clínico que puede alcanzar el stock de salud.'], explanation: 'δ es la tasa de depreciación: la fracción del stock que se pierde en un período. La inversión neta es I(t), y el índice del modelo no tiene un techo clínico de 100.' },
  { lesson: 'econ-grossman', type: 'mc', prompt: 'El apunte relaciona envejecimiento y educación con el stock de salud. ¿Cómo deben interpretarse esas relaciones?', options: ['Como mecanismos del modelo, no como leyes deterministas individuales.', 'Como predicciones clínicas exactas para cada paciente individual.', 'Como un límite clínico que fija el índice de salud en un máximo de 100.', 'Como evidencia causal suficiente a partir de una sola asociación.'], explanation: 'El apunte asocia envejecimiento con mayor depreciación y educación con mayor eficiencia para producir salud, pero no son leyes deterministas individuales. No debe confundirse asociación con causalidad.' },
  { lesson: 'econ-grossman', type: 'tf', prompt: 'En el modelo de Grossman, la salud brinda bienestar directo y, además, permite realizar actividades como trabajar.', answer: true, explanation: 'Correcto. La salud se valora por sus beneficios de consumo (bienestar directo) y de inversión (permite realizar actividades).' },
  { lesson: 'econ-grossman', type: 'tf', prompt: 'En el modelo de Grossman, la inversión I(t) se mide en las mismas unidades del stock H y no simplemente en pesos gastados.', answer: true, explanation: 'Correcto. I(t) es inversión neta agregada al stock en unidades de H. Por eso no se debe asumir que cualquier gasto en pesos tiene el mismo rendimiento en salud.' },
  { lesson: 'econ-grossman', type: 'tf', prompt: 'Los parámetros del modelo de Grossman, como δ, son medidas clínicas que predicen la salud futura de cada persona.', answer: false, explanation: 'Falso. El modelo ayuda a pensar mecanismos; sus parámetros no son medidas clínicas ni predicciones individuales, y el índice de salud es abstracto.' },
  { lesson: 'econ-grossman', type: 'tf', prompt: 'Según el apunte, cualquier gasto en atención médica tiene el mismo rendimiento en la producción de salud.', answer: false, explanation: 'Falso. El material advierte que no se debe asumir que cualquier gasto tiene el mismo rendimiento ni confundir asociación con causalidad.' },

  // Productividad marginal y capacidad
  { lesson: 'econ-productividad', type: 'mc', prompt: 'Ejercicio simulado: con 1, 2, 3 y 4 controles anuales, el índice de salud total de un grupo es 50, 62, 70 y 74. ¿Cuál es la productividad marginal del cuarto control?', options: ['4 unidades', '74 unidades', '18,5 unidades', '24 unidades'], explanation: 'La productividad marginal es el cambio del total al agregar una unidad: 74 − 70 = 4. El 74 es el total y 18,5 es el promedio (74/4), no el aporte marginal.' },
  { lesson: 'econ-productividad', type: 'mc', prompt: 'Ejercicio simulado: el índice de salud total pasa de 60 a 66, luego a 69 y después a 67 al agregar tres unidades sucesivas de atención. ¿Qué describen los aportes marginales?', options: ['Son 6, 3 y −2: decrecen y el último reduce el total.', 'Son 66, 69 y 67: el total aumenta en todo el tramo.', 'Son 6, 9 y 7: los aportes son siempre positivos.', 'Son 6, 3 y 2: decrecen, pero ninguno es negativo.'], explanation: 'Los aportes son 66 − 60 = 6, 69 − 66 = 3 y 67 − 69 = −2. Decrecen y el último es negativo, por lo que el total cae en esa unidad; 6, 9 y 7 son diferencias acumuladas respecto de 60.' },
  { lesson: 'econ-productividad', type: 'mc', prompt: 'Si la productividad marginal de un insumo es exactamente cero en un margen, ¿qué ocurre con el resultado total de salud?', options: ['Deja de aumentar en ese margen.', 'Cae inmediatamente a cero.', 'Sigue aumentando al mismo ritmo.', 'Disminuye en la misma magnitud.'], explanation: 'Con aporte marginal cero el total se mantiene en ese margen: deja de aumentar, pero no cae. El total disminuye solo cuando el aporte marginal es negativo.' },
  { lesson: 'econ-productividad', type: 'mc', prompt: '¿Cómo deben interpretarse los valores 95, 80, 45 y −5 de la figura del apunte sobre APS/vacunación, urgencias, seguimiento y exámenes redundantes?', options: ['Como un índice ilustrativo, sin población ni denominador especificados.', 'Como porcentajes de eficacia clínica medidos en cada intervención.', 'Como una prioridad clínica válida para cualquier paciente.', 'Como cuatro etapas sucesivas en la atención clínica de un mismo paciente.'], explanation: 'La figura no especifica población, denominador ni estimación; por eso sus valores se usan como índice ilustrativo. No son eficacias clínicas, prioridades generalizables ni necesariamente etapas del mismo paciente.' },
  { lesson: 'econ-productividad', type: 'mc', prompt: '¿Qué es la iatrogenia en el contexto de la productividad de la atención?', options: ['El daño causado por la propia atención de salud.', 'El beneficio neto positivo de una intervención.', 'La depreciación natural del stock de salud.', 'La falta de atención por barreras de acceso.'], explanation: 'Iatrogenia es el daño causado por la atención. Puede existir incluso cuando el beneficio neto de una intervención es positivo; no equivale a la depreciación del modelo de Grossman.' },
  { lesson: 'econ-productividad', type: 'mc', prompt: 'Un hospital contrata más cirujanos, pero mantiene el mismo número de pabellones y equipos. ¿Qué concepto ilustra mejor esta situación?', options: ['Rendimiento marginal de un insumo con un factor limitante fijo.', 'Economías de escala de largo plazo con todos los factores ajustables.', 'Externalidad positiva sobre los demás hospitales de la red.', 'Dilución del costo fijo gracias a una mayor demanda efectiva.'], explanation: 'Agregar cirujanos con pabellones fijos estudia el rendimiento marginal de un insumo en el corto plazo, donde la capacidad puede limitar. Las economías de escala exigen ampliar y ajustar todos los factores.' },
  { lesson: 'econ-productividad', type: 'tf', prompt: 'La productividad marginal de la atención, ΔH/ΔM, mide cuánto cambia el resultado de salud al agregar atención manteniendo constantes los demás factores.', answer: true, explanation: 'Correcto. Es la definición del material: el cambio en el resultado de salud al agregar atención, con los otros factores fijos.' },
  { lesson: 'econ-productividad', type: 'tf', prompt: 'Si el aporte marginal de la atención baja de 8 a 4 unidades, el resultado total de salud sigue aumentando.', answer: true, explanation: 'Correcto. El aporte disminuye, pero sigue siendo positivo; por eso el total aumenta, aunque más lentamente. Decreciente no significa negativo.' },
  { lesson: 'econ-productividad', type: 'tf', prompt: 'Una productividad marginal decreciente implica necesariamente que el resultado total de salud está cayendo.', answer: false, explanation: 'Falso. Decreciente no significa negativo: mientras el aporte marginal sea positivo, el total sigue aumentando. El total cae solo en el tramo donde el aporte marginal es negativo.' },
  { lesson: 'econ-productividad', type: 'tf', prompt: 'La iatrogenia aparece exclusivamente después de superar una cantidad óptima universal de atención.', answer: false, explanation: 'Falso. La iatrogenia, daño causado por la atención, puede existir aun cuando el beneficio neto de una intervención sea positivo; no depende de un óptimo universal.' },

  // Oferta, demanda y equilibrio
  { lesson: 'econ-mercado', type: 'mc', prompt: 'Ejercicio simulado: la demanda de controles es P = 2.000 − 250Q y la oferta es P = 500 + 250Q. ¿Cuál es el equilibrio?', options: ['Q = 3 y P = 1.250', 'Q = 4 y P = 1.000', 'Q = 2 y P = 1.000', 'Q = 6 y P = 500'], explanation: 'En equilibrio Qd = Qs al mismo precio: 2.000 − 250Q = 500 + 250Q, luego 500Q = 1.500 y Q = 3; P = 500 + 250 × 3 = 1.250. Los otros puntos están sobre una sola curva, no en el cruce.' },
  { lesson: 'econ-mercado', type: 'mc', prompt: 'Ejercicio simulado: a un precio de $8.000, se demandan 40 exámenes y se ofrecen 70. ¿Qué situación existe a ese precio?', options: ['Exceso de oferta de 30 exámenes.', 'Exceso de demanda de 30 exámenes.', 'Equilibrio, porque ambas cantidades son positivas.', 'Exceso de oferta de 110 exámenes.'], explanation: 'Como la cantidad ofrecida supera a la demandada, hay exceso de oferta: 70 − 40 = 30. El equilibrio exige Qd = Qs al mismo precio, no solo cantidades positivas.' },
  { lesson: 'econ-mercado', type: 'mc', prompt: 'Sube el precio de una consulta particular y ningún otro factor cambia. ¿Qué ocurre en el gráfico de demanda?', options: ['Baja la cantidad demandada: hay un movimiento sobre la misma curva.', 'La curva de demanda completa se desplaza hacia la izquierda.', 'La curva de demanda completa se desplaza hacia la derecha.', 'Aumenta la cantidad demandada, con un movimiento sobre la misma curva.'], explanation: 'Un cambio en el precio propio produce un movimiento a lo largo de la curva: un precio mayor reduce la cantidad demandada. Los desplazamientos se deben a ingreso, preferencias u otros determinantes.' },
  { lesson: 'econ-mercado', type: 'mc', prompt: 'Bajan los costos de los reactivos que utiliza un laboratorio clínico. ¿Qué efecto esperado describe el material?', options: ['La oferta puede aumentar, desplazándose hacia abajo y a la derecha.', 'La demanda se desplaza hacia la derecha porque bajan los costos del laboratorio.', 'Solo hay un movimiento a lo largo de la misma curva de oferta.', 'La oferta se desplaza hacia arriba y a la izquierda.'], explanation: 'Los costos son un determinante de la oferta: menores costos pueden aumentarla, desplazándola hacia abajo/derecha. Si los costos suben ocurre lo contrario, hacia arriba/izquierda.' },
  { lesson: 'econ-mercado', type: 'mc', prompt: 'Aumenta el ingreso de los hogares y, manteniendo lo demás constante, disminuye la demanda de un servicio. ¿Cómo se clasifica ese bien?', options: ['Como un bien inferior.', 'Como un bien normal.', 'Como un bien complementario.', 'Como un bien público puro.'], explanation: 'Para un bien normal, más ingreso desplaza la demanda a la derecha. Si la demanda cae al subir el ingreso, el bien es inferior. Complementario se refiere a la relación con otro bien, no al ingreso.' },
  { lesson: 'econ-mercado', type: 'mc', prompt: 'En economía, ¿qué diferencia a un bien sustituto de un bien complementario?', options: ['El sustituto satisface una necesidad parecida; el complemento se usa en conjunto.', 'El sustituto se usa en conjunto; el complemento satisface una necesidad parecida.', 'El sustituto es un bien normal; el complemento es siempre un bien inferior.', 'El sustituto desplaza la oferta; el complemento solo mueve sobre la demanda.'], explanation: 'Un sustituto puede reemplazar a otro bien porque satisface una necesidad parecida; un complemento se consume junto con otro. La clasificación normal/inferior se refiere a la respuesta frente al ingreso.' },
  { lesson: 'econ-mercado', type: 'tf', prompt: 'El equilibrio de mercado requiere que la cantidad demandada y la ofrecida sean iguales a un mismo precio.', answer: true, explanation: 'Correcto. El equilibrio está en el cruce de las curvas: Qd = Qs al mismo precio. A otros precios hay exceso de oferta o de demanda.' },
  { lesson: 'econ-mercado', type: 'tf', prompt: 'El modelo competitivo de oferta y demanda no representa automáticamente mercados con listas de espera, tarifas administradas o poder de mercado.', answer: true, explanation: 'Correcto. El modelo es una herramienta; en salud existen tarifas administradas, barreras de acceso y poder de mercado que requieren un análisis adicional.' },
  { lesson: 'econ-mercado', type: 'tf', prompt: 'La curva de demanda incluye automáticamente a toda persona que necesita un examen, aunque no pueda pagarlo.', answer: false, explanation: 'Falso. La demanda relaciona precios con cantidades que se desean y pueden comprar. Necesidad sanitaria y demanda efectiva son conceptos distintos.' },
  { lesson: 'econ-mercado', type: 'tf', prompt: 'Toda lista de espera en salud se explica únicamente por precios que no logran ajustarse.', answer: false, explanation: 'Falso. El material no presupone ajuste inmediato ni que toda lista de espera se explique solo por precios; intervienen también tarifas administradas, barreras de acceso y poder de mercado.' },

  // Elasticidad y gasto total
  { lesson: 'econ-elasticidad', type: 'mc', prompt: 'Ejercicio simulado: el precio de un examen sube de $10.000 a $14.000 y la cantidad demandada baja de 200 a 160. ¿Cuál es la elasticidad arco por punto medio y cómo se clasifica?', options: ['−0,67; inelástica', '−0,50; inelástica', '−1,50; elástica', '−0,67; elástica'], explanation: 'ΔQ/promedio Q = −40/180 = −22,22%; ΔP/promedio P = 4.000/12.000 = 33,33%; E = −0,67. Como |E| < 1, es inelástica. El −0,50 usa los valores iniciales como base en vez del punto medio.' },
  { lesson: 'econ-elasticidad', type: 'mc', prompt: 'Ejercicio simulado: la tarifa de una sesión de kinesiología baja de $30.000 a $20.000 y las sesiones aumentan de 100 a 150. ¿Cuál es la elasticidad arco por punto medio?', options: ['−1,00; unitaria', '−1,50; elástica', '−0,67; inelástica', '−0,40; inelástica'], explanation: 'ΔQ/promedio Q = 50/125 = 40%; ΔP/promedio P = −10.000/25.000 = −40%; E = −1,00, unitaria, y el gasto se mantiene en $3.000.000. El −1,50 surge de usar los valores iniciales como base (50% / −33,33%).' },
  { lesson: 'econ-elasticidad', type: 'mc', prompt: 'Ejercicio simulado: el precio de un procedimiento sube de $40.000 a $50.000 y la cantidad demandada baja de 300 a 255. ¿Qué ocurre con el gasto total entre esos puntos?', options: ['Aumenta de $12.000.000 a $12.750.000.', 'Disminuye de $12.000.000 a $10.200.000.', 'Aumenta de $12.000.000 a $15.000.000.', 'Se mantiene en $12.000.000.'], explanation: 'Gasto = P × Q: 40.000 × 300 = $12.000.000 y 50.000 × 255 = $12.750.000. La demanda es inelástica (E ≈ −0,73), así que el alza de precio eleva el gasto; $10.200.000 combina el precio antiguo con la cantidad nueva.' },
  { lesson: 'econ-elasticidad', type: 'mc', prompt: '¿Cómo se clasifica una demanda cuya elasticidad precio es −1,8?', options: ['Elástica, porque su valor absoluto es mayor que 1.', 'Inelástica, porque −1,8 es un número menor que 1.', 'Unitaria, porque el signo negativo compensa su magnitud.', 'Inelástica, porque el signo negativo indica poca sensibilidad.'], explanation: 'La clasificación usa |E|: |−1,8| = 1,8 > 1, por lo que es elástica. El signo negativo solo indica que precio y cantidad se mueven en sentido opuesto en una demanda decreciente.' },
  { lesson: 'econ-elasticidad', type: 'mc', prompt: 'Entre dos precios, la demanda de una prestación es inelástica. ¿Qué ocurre con el ingreso total del prestador si sube el precio?', options: ['Aumenta entre esos puntos, aunque eso no implica mayor utilidad.', 'Disminuye, porque la cantidad demandada cae al subir el precio.', 'Se mantiene igual, porque la elasticidad es menor que 1.', 'Aumenta y equivale exactamente a una mayor utilidad.'], explanation: 'Con demanda inelástica, la cantidad cae proporcionalmente menos de lo que sube el precio, así que P × Q aumenta. Ingreso total no es utilidad: aún deben restarse los costos.' },
  { lesson: 'econ-elasticidad', type: 'mc', prompt: 'La elasticidad cruzada entre dos prestaciones es positiva, manteniendo lo demás constante. ¿Con qué relación es compatible?', options: ['Con que sean sustitutos.', 'Con que sean complementos.', 'Con que ambas sean bienes inferiores.', 'Con una demanda perfectamente inelástica.'], explanation: 'Elasticidad cruzada positiva es compatible con sustitutos: si sube el precio de una, aumenta la demanda de la otra. Con complementos, la elasticidad cruzada es negativa.' },
  { lesson: 'econ-elasticidad', type: 'tf', prompt: 'La elasticidad precio no tiene unidades, porque es un cociente entre dos cambios porcentuales.', answer: true, explanation: 'Correcto. Al dividir un cambio porcentual en cantidad por uno en precio, las unidades se cancelan; por eso permite comparar bienes medidos en unidades distintas.' },
  { lesson: 'econ-elasticidad', type: 'tf', prompt: 'A lo largo de una curva de demanda lineal, la elasticidad precio puede tomar valores distintos.', answer: true, explanation: 'Correcto. Aunque la pendiente sea constante, los cambios porcentuales dependen del punto observado; por eso la elasticidad puede variar a lo largo de una demanda lineal.' },
  { lesson: 'econ-elasticidad', type: 'tf', prompt: 'La pendiente de una curva de demanda basta para comparar elasticidades, aunque cambien las unidades o la escala del gráfico.', answer: false, explanation: 'Falso. Pendiente no es elasticidad. Cambiar unidades o escalas altera la apariencia de la curva sin cambiar la elasticidad, que además depende del punto observado.' },
  { lesson: 'econ-elasticidad', type: 'tf', prompt: 'Con el método del punto medio, la elasticidad entre dos puntos cambia según si el precio sube o baja.', answer: false, explanation: 'Falso. El punto medio usa el promedio de ambos valores como base, por lo que obtiene la misma elasticidad al recorrer los puntos en cualquier sentido.' },

  // Monopolio, ingreso marginal y pérdida social
  { lesson: 'econ-monopolio', type: 'mc', prompt: 'Ejercicio simulado: un monopolista de precio único enfrenta P = 1.400 − 100Q y tiene CMg = 200 + 100Q. ¿Qué cantidad produce y a qué precio vende?', options: ['Qm = 4 y Pm = $1.000', 'Qm = 4 y Pm = $600', 'Qm = 6 y Pm = $800', 'Qm = 7 y Pm = $700'], explanation: 'IMg = 1.400 − 200Q; al igualarlo a CMg: 1.400 − 200Q = 200 + 100Q, Q = 4. El precio se lee en la demanda: 1.400 − 100 × 4 = 1.000. $600 es la altura del cruce IMg = CMg, no el precio.' },
  { lesson: 'econ-monopolio', type: 'mc', prompt: 'Ejercicio simulado: con demanda P = 1.600 − 100Q y CMg = 400 + 200Q, ¿cuál es la pérdida social del monopolio de precio único frente a la competencia?', options: ['150 unidades monetarias', '300 unidades monetarias', '50 unidades monetarias', '450 unidades monetarias'], explanation: 'Qc = 1.200/300 = 4 y Qm = 1.200/400 = 3; Pm = 1.600 − 300 = 1.300 y CMg(3) = 1.000. Pérdida = ½ × (4 − 3) × (1.300 − 1.000) = 150. El 300 olvida el factor ½.' },
  { lesson: 'econ-monopolio', type: 'mc', prompt: 'Ejercicio simulado: un monopolista enfrenta la demanda P = 900 − 50Q. ¿Cuánto vale su ingreso marginal en Q = 6?', options: ['$300', '$600', '$3.600', '$750'], explanation: 'Con P = a − bQ, IMg = a − 2bQ = 900 − 2 × 50 × 6 = 300, por debajo del precio de 600. El $600 confunde IMg con el precio y $3.600 es el ingreso total (600 × 6).' },
  { lesson: 'econ-monopolio', type: 'mc', prompt: '¿Por qué una empresa tomadora de precios en competencia enfrenta un ingreso marginal igual al precio?', options: ['Porque puede vender más sin reducir el precio de mercado.', 'Porque enfrenta por sí sola toda la demanda del mercado.', 'Porque su costo marginal es siempre igual a cero.', 'Porque cobra precios distintos a cada comprador.'], explanation: 'La empresa competitiva toma el precio como dado: cada unidad adicional se vende al mismo precio, así que IMg = P. El monopolista, en cambio, enfrenta toda la demanda y debe bajar el precio para vender más.' },
  { lesson: 'econ-monopolio', type: 'mc', prompt: '¿Qué diferencia a un monopolio de un monopsonio?', options: ['El monopolio tiene un solo vendedor; el monopsonio, un solo comprador.', 'El monopolio tiene un solo comprador; el monopsonio, un solo vendedor.', 'El monopolio discrimina precios; el monopsonio cobra un precio único.', 'Son el mismo caso y se analizan con las mismas curvas.'], explanation: 'Monopolio significa un vendedor; monopsonio, un comprador. El monopsonio requiere un análisis distinto del modelo de ingreso marginal del monopolista.' },
  { lesson: 'econ-monopolio', type: 'mc', prompt: 'En el modelo lineal del laboratorio, con P = a − bQ y CMg = c + dQ, ¿qué ocurre si a ≤ c?', options: ['No existe producción positiva rentable en el modelo.', 'El monopolista produce más que la competencia.', 'La pérdida social alcanza su valor máximo.', 'El precio pasa a leerse en la curva de IMg.'], explanation: 'Si a ≤ c, el costo marginal de la primera unidad (c) ya iguala o supera la máxima disposición a pagar (a); entonces Qc = (a − c)/(b + d) y Qm = (a − c)/(2b + d) no son positivas.' },
  { lesson: 'econ-monopolio', type: 'tf', prompt: 'La comparación entre competencia y monopolio del laboratorio supone la misma demanda y tecnología, sin discriminación de precios ni externalidades.', answer: true, explanation: 'Correcto. Esas condiciones permiten atribuir la diferencia de cantidad y precio a la estructura de mercado. Además, el modelo no incluye costos fijos.' },
  { lesson: 'econ-monopolio', type: 'tf', prompt: 'Con demanda lineal P = a − bQ, el ingreso marginal IMg = a − 2bQ tiene el mismo intercepto que la demanda y una pendiente dos veces mayor en valor absoluto.', answer: true, explanation: 'Correcto. El ingreso total es aQ − bQ² y su derivada es a − 2bQ: mismo intercepto a y pendiente −2b. Por eso IMg queda por debajo del precio para Q > 0.' },
  { lesson: 'econ-monopolio', type: 'tf', prompt: 'El monopolista de precio único fija su precio a la altura del cruce entre ingreso marginal y costo marginal.', answer: false, explanation: 'Falso. El cruce IMg = CMg define la cantidad Qm; el precio se lee en la curva de demanda a esa cantidad, por encima de IMg.' },
  { lesson: 'econ-monopolio', type: 'tf', prompt: 'La pérdida social del monopolio equivale a la transferencia de ingreso desde los compradores hacia el vendedor.', answer: false, explanation: 'Falso. La pérdida social corresponde a intercambios no realizados, entre Qm y Qc, cuyo beneficio marginal supera el costo marginal; la transferencia es un efecto distinto.' },

  // Seguros, copagos y experimento RAND
  { lesson: 'econ-seguros', type: 'mc', prompt: 'Ejercicio simulado: la probabilidad anual de un evento es 2% y su costo es $3.000.000. ¿Cuál es la prima mensual esperada antes de recargos?', options: ['$5.000', '$60.000', '$250.000', '$83.333'], explanation: 'Costo esperado anual = 0,02 × $3.000.000 = $60.000; dividido entre 12 da $5.000 al mes, antes de recargos. $83.333 sería ahorrar el costo completo en 36 meses, un mecanismo distinto.' },
  { lesson: 'econ-seguros', type: 'mc', prompt: 'Ejercicio simulado: el precio total de una consulta es $30.000, el copago es 20% y la demanda es Q = máximo(0, 400 − 0,01 × precio de bolsillo). ¿Cuántas consultas se demandan y cuánto gasta el asegurador?', options: ['340 consultas; el asegurador gasta $8.160.000.', '340 consultas; el asegurador gasta $10.200.000.', '340 consultas; el asegurador gasta $2.040.000.', '100 consultas; el asegurador gasta $2.400.000.'], explanation: 'Precio de bolsillo = 30.000 × 0,20 = $6.000; Q = 400 − 60 = 340. El asegurador paga $24.000 por consulta: 340 × 24.000 = $8.160.000. $10.200.000 es el gasto total y $2.040.000 la parte del paciente.' },
  { lesson: 'econ-seguros', type: 'mc', prompt: 'Después de contratar un seguro con cobertura completa, una persona usa más consultas que antes. ¿Qué concepto describe este cambio?', options: ['Riesgo moral.', 'Selección adversa.', 'Selección de riesgos.', 'Ajuste de riesgo.'], explanation: 'Riesgo moral es el cambio de conducta tras tener cobertura. La selección adversa, en cambio, se refiere a información que influye en quién contrata. Un mayor uso no demuestra por sí solo que la atención sea innecesaria.' },
  { lesson: 'econ-seguros', type: 'mc', prompt: 'Personas que saben que tienen mayor riesgo de enfermar contratan más cobertura, y la aseguradora no puede distinguirlas. ¿Qué concepto describe esta situación?', options: ['Selección adversa.', 'Riesgo moral.', 'Selección de riesgos.', 'Externalidad negativa.'], explanation: 'La selección adversa describe diferencias de información que influyen en quién contrata cobertura. No es riesgo moral, que es un cambio de conducta posterior a la cobertura.' },
  { lesson: 'econ-seguros', type: 'mc', prompt: 'Una aseguradora diseña planes y publicidad para atraer a personas jóvenes y sanas, de menor costo esperado. ¿Qué concepto describe esta estrategia?', options: ['Selección de riesgos.', 'Selección adversa.', 'Riesgo moral.', 'Ajuste de riesgo.'], explanation: 'La selección de riesgos es una estrategia del asegurador para atraer personas de menor costo. La selección adversa surge de la información de quienes contratan, y el ajuste de riesgo busca compensar diferencias de costo esperado.' },
  { lesson: 'econ-seguros', type: 'mc', prompt: '¿Qué encontró el experimento de seguros de RAND (1974–1982) sobre la participación del paciente en el costo?', options: ['Redujo el uso de atención, tanto muy efectiva como menos efectiva.', 'Redujo solo la atención innecesaria, sin afectar la atención efectiva.', 'Aumentó la utilización de servicios en todos los grupos.', 'No tuvo efecto alguno sobre la utilización de servicios.'], explanation: 'RAND encontró menor utilización con participación en el costo, y esa reducción alcanzó atención muy efectiva y menos efectiva. No permite concluir que toda la atención evitada fuera innecesaria.' },
  { lesson: 'econ-seguros', type: 'tf', prompt: 'Cuando el copago es cero, el gasto total en la prestación no desaparece: lo financia por completo el asegurador.', answer: true, explanation: 'Correcto. El gasto total es precio × Q y se reparte entre paciente y asegurador. Con copago cero el paciente no paga de su bolsillo, pero el costo sigue existiendo.' },
  { lesson: 'econ-seguros', type: 'tf', prompt: 'Un ajuste de riesgo busca compensar diferencias de costos esperados entre las personas aseguradas.', answer: true, explanation: 'Correcto. Al compensar diferencias de costo esperado, el ajuste de riesgo puede reducir el incentivo del asegurador a atraer solo a personas de menor costo.' },
  { lesson: 'econ-seguros', type: 'tf', prompt: 'Agrupar riesgos en un seguro elimina toda la incertidumbre, incluidos los riesgos correlacionados.', answer: false, explanation: 'Falso. El seguro reparte costos inciertos entre muchas personas, pero agrupar riesgos no elimina toda incertidumbre ni los riesgos correlacionados.' },
  { lesson: 'econ-seguros', type: 'tf', prompt: 'Si el copago baja de 50% a 25%, el precio total de la prestación también baja a la mitad.', answer: false, explanation: 'Falso. El precio total se mantiene; cambian el precio de bolsillo y quién financia cada parte. Además, el menor copago puede elevar el uso y el gasto del asegurador.' },

  // Costos y economías de escala
  { lesson: 'econ-escala', type: 'mc', prompt: 'Ejercicio simulado: un centro de imagenología tiene F = $2.000.000 al mes, v = $10.000 por examen y k = 0. ¿En qué porcentaje cambia el costo medio al pasar de 200 a 400 exámenes?', options: ['−25%', '+50%', '−50%', '−33,33%'], explanation: 'CMe(200) = 2.000.000/200 + 10.000 = $20.000 y CMe(400) = $15.000; (15.000/20.000 − 1) × 100 = −25%. El +50% es el aumento del costo total y el −50% solo el del costo fijo por examen.' },
  { lesson: 'econ-escala', type: 'mc', prompt: 'Ejercicio simulado: CT = F + vQ + kQ², con F = $500.000, v = $4.000 y k = 10. ¿Cuál es el costo marginal cuando Q = 100?', options: ['$6.000', '$10.000', '$5.000', '$1.000.000'], explanation: 'CMg = v + 2kQ = 4.000 + 2 × 10 × 100 = $6.000. El $10.000 es el costo medio (F/Q + v + kQ) y $1.000.000 es el costo total; medio, marginal y total son medidas distintas.' },
  { lesson: 'econ-escala', type: 'mc', prompt: 'Ejercicio simulado: en el largo plazo, CT = C₀ × (Q/Q₀)^α con C₀ = $10.000.000, Q₀ = 1.000 y α = 0,8. Si Q se duplica a 2.000, ¿qué ocurre con el costo medio?', options: ['Baja de $10.000 a cerca de $8.706: economías de escala.', 'Se mantiene en $10.000: costo medio constante.', 'Sube de $10.000 a cerca de $11.487: deseconomías.', 'Baja de $10.000 a $5.000: el costo total no cambia.'], explanation: 'CT = 10.000.000 × 2^0,8 ≈ $17.411.011 y CMe = 17.411.011/2.000 ≈ $8.706, menor que 10.000.000/1.000 = $10.000. Con α < 1, duplicar Q aumenta CT menos del doble.' },
  { lesson: 'econ-escala', type: 'mc', prompt: 'Un laboratorio duplica sus exámenes sin ampliar equipos ni instalaciones, y su costo por examen cae. ¿Qué describe mejor este resultado?', options: ['Dilución del costo fijo en el corto plazo.', 'Economías de escala de largo plazo demostradas.', 'Deseconomías de escala por congestión.', 'Una disminución del costo total del laboratorio.'], explanation: 'Sin ajustar todos los insumos, la caída del costo medio refleja que el mismo costo fijo se reparte entre más exámenes. Las economías de escala de largo plazo requieren evaluar el ajuste de todos los factores.' },
  { lesson: 'econ-escala', type: 'mc', prompt: 'En el modelo de largo plazo CT = C₀ × (Q/Q₀)^α, ¿qué indica un valor α > 1?', options: ['Deseconomías de escala: el costo medio sube al ampliar la escala.', 'Economías de escala: el costo medio baja al ampliar la producción.', 'Costo medio constante en todo el tramo analizado.', 'Dilución del costo fijo entre más atenciones en el corto plazo.'], explanation: 'Con α > 1, el costo total crece más que proporcionalmente que Q, por lo que el costo medio sube: deseconomías. Con α < 1 hay economías y con α = 1 el costo medio se mantiene.' },
  { lesson: 'econ-escala', type: 'mc', prompt: 'Al comparar el costo medio de dos hospitales para evaluar economías de escala, ¿qué condición exige el material?', options: ['Que tengan calidad y complejidad equivalentes.', 'Que tengan el mismo presupuesto total anual.', 'Que tengan exactamente el mismo número de camas.', 'Que ambos operen con costo fijo igual a cero.'], explanation: 'Comparar costos medios solo es válido con productos, calidad y complejidad comparables; de lo contrario, la diferencia puede reflejar pacientes o servicios distintos y no un efecto de escala.' },
  { lesson: 'econ-escala', type: 'tf', prompt: 'Si al ajustar todos los insumos la producción se duplica y el costo total también se duplica, el costo medio permanece constante.', answer: true, explanation: 'Correcto. CMe = CT/Q: si numerador y denominador se duplican, el cociente no cambia. En el modelo de largo plazo corresponde a α = 1.' },
  { lesson: 'econ-escala', type: 'tf', prompt: 'Centralizar la producción para aprovechar economías de escala puede aumentar los costos de acceso para los pacientes.', answer: true, explanation: 'Correcto. El material advierte que centralizar puede elevar los costos de acceso para pacientes, por lo que el análisis no debe limitarse al costo medio del establecimiento.' },
  { lesson: 'econ-escala', type: 'tf', prompt: 'Costo medio y costo marginal son dos nombres para la misma medida: el costo total dividido por la cantidad.', answer: false, explanation: 'Falso. Costo medio = CT/Q; costo marginal = costo de una unidad adicional. En el corto plazo, CMe = F/Q + v + kQ y CMg = v + 2kQ.' },
  { lesson: 'econ-escala', type: 'tf', prompt: 'Si un modelo muestra economías de escala en un tramo, crecer indefinidamente siempre es óptimo.', answer: false, explanation: 'Falso. El modelo describe un tramo y no implica que crecer indefinidamente sea óptimo; además, deben considerarse calidad, complejidad y acceso de los pacientes.' }
];
